  var n = normalize(cross(dpdx(in.worldPos), dpdy(in.worldPos)));
  // Orient toward the camera so the visible face is always lit regardless of
  // triangle winding or whether we are looking at a cliff side.
  let toCam = camera.camPos - in.worldPos;
  if (dot(n, toCam) < 0.0) {
    n = -n;
  }

  // Simple directional (lambert) light + ambient term.
  let lightDir = normalize(vec3<f32>(0.45, 1.0, 0.35));
  let diffuse  = max(dot(n, lightDir), 0.0);
  let shade    = 0.35 + diffuse * 0.75;

  // Coloring thresholded on the *interpolated* world-space Y, evaluated per
  // fragment -> crisp bands, not blended gradients. Bands are tied to the water
  // plane (Y = -0.125 = -LEVEL_HEIGHT/2). Because the water surface is flat, the
  // sea-floor height *is* the water depth, so the two submerged tones read as
  // two water depths once the transparent blue is blended over them:
  //   Y > 0                  -> green (land)
  //   -0.125 < Y <= 0        -> sand (dry beach; lower edge on the water line)
  //   -0.375 < Y <= -0.125   -> shallow floor (light  -> light water)
  //   Y <= -0.375            -> deep floor    (dark   -> dark water)
  let land    = vec3<f32>(0.24, 0.50, 0.19); // land -> green
  let sand    = vec3<f32>(0.78, 0.71, 0.50); // beach -> yellow-brown
  let shallow = vec3<f32>(0.40, 0.45, 0.48); // shallow sea floor
  let deep    = vec3<f32>(0.30, 0.32, 0.36); // deep sea floor
  var base  = land;
  base = select(base, sand, in.worldPos.y <= 0.0);
  base = select(base, shallow, in.worldPos.y <= -0.125);
  base = select(base, deep, in.worldPos.y <= -0.375);

  // Subtle TTD-style tile grid: tile boundaries fall on integer X/Z, so darken
  // fragments close to an integer line. fwidth keeps the line ~1px wide on
  // screen regardless of slope/zoom; the fade hides it when tiles shrink below
  // a few pixels so distant terrain doesn't turn into a dark mush.
  let coord = in.worldPos.xz;
  let deriv = fwidth(coord);
  let distToLine = abs(fract(coord - 0.5) - 0.5) / max(deriv, vec2<f32>(1e-5));
  let nearest = min(distToLine.x, distToLine.y);
  var grid = 1.0 - clamp(nearest, 0.0, 1.0);
